"""Seed fixtures from packages/contracts/fixtures (generated by svoi_api.seed)."""

import json
import os
from dataclasses import dataclass
from functools import cache
from pathlib import Path
from typing import Any

DEFAULT_DIR = Path(__file__).resolve().parents[4] / "packages" / "contracts" / "fixtures"


def fixtures_dir() -> Path:
    """SVOI_FIXTURES_DIR overrides the repo path (the bot image copies fixtures elsewhere)."""
    return Path(os.environ.get("SVOI_FIXTURES_DIR", DEFAULT_DIR))


@dataclass(frozen=True)
class Fixtures:
    cities: list[dict[str, Any]]
    categories: list[dict[str, Any]]
    interests: list[dict[str, Any]]
    goals: list[dict[str, Any]]
    prompts: list[dict[str, Any]]
    clarifications: list[dict[str, Any]]
    institutions: list[dict[str, Any]]
    profiles: list[dict[str, Any]]


@cache
def load(directory: Path | None = None) -> Fixtures:
    """Read every fixture file once per directory."""
    base = directory or fixtures_dir()

    def read(name: str) -> list[dict[str, Any]]:
        data: list[dict[str, Any]] = json.loads((base / f"{name}.json").read_text("utf-8"))
        return data

    return Fixtures(
        cities=read("cities"),
        categories=read("interest_categories"),
        interests=read("interests"),
        goals=read("goals"),
        prompts=read("prompts"),
        clarifications=read("clarifications"),
        institutions=read("institutions"),
        profiles=read("profiles"),
    )
